-- Comentarios da Lei 15.040/2024, lote 6 (arts. 101 a 120). Autorizados pela Jessica em 22/10/2026; so a partir do texto no banco.
-- Reverter: update legislacao set contexto=null, aplicacao_pratica=null where codigo='lei15040' and numero between 101 and 120 and paragrafo is null and inciso is null;
update legislacao l set contexto=v.c, aplicacao_pratica=v.a from (values
(101,'Cientificação da seguradora e chamamento ao processo','Quando a pretensão do prejudicado for exercida exclusivamente contra o segurado, este será obrigado a cientificar a seguradora, tão logo seja citado para responder à demanda, e a disponibilizar os elementos necessários para o conhecimento do processo. O parágrafo único dispõe que o segurado poderá chamar a seguradora a integrar o processo, na condição de litisconsorte, sem responsabilidade solidária.'),
(102,'Ação do prejudicado contra a seguradora','Os prejudicados poderão exercer seu direito de ação contra a seguradora, desde que em litisconsórcio passivo com o segurado. O parágrafo único dispõe que o litisconsórcio será dispensado quando o segurado não tiver domicílio no Brasil.'),
(103,'Defesas fundadas no contrato oponíveis aos prejudicados','Salvo disposição legal em contrário, a seguradora poderá opor aos prejudicados as defesas fundadas no contrato de seguro que tiver contra o segurado antes do sinistro.'),
(104,'Defesas próprias da seguradora contra os terceiros prejudicados','A seguradora poderá opor aos terceiros prejudicados todas as defesas que contra eles possuir.'),
(105,'Informação aos terceiros prejudicados sobre o seguro','O segurado deverá empreender os melhores esforços para informar os terceiros prejudicados sobre a existência e o conteúdo do seguro contratado.'),
(106,'Transação da seguradora com os prejudicados','Salvo disposição em contrário, a seguradora poderá celebrar transação com os prejudicados, o que não implicará o reconhecimento de responsabilidade do segurado nem prejudicará aqueles a quem é imputada a responsabilidade.'),
(107,'Pluralidade de prejudicados','Se houver pluralidade de prejudicados em um mesmo evento, a seguradora ficará liberada com a prestação da totalidade das indenizações decorrentes da garantia do seguro a um ou mais prejudicados, sempre que ignorar a existência dos demais.'),
(108,'Transferência do interesse garantido e cessão do seguro','A transferência do interesse garantido implica a cessão do seguro correspondente, obrigando-se o cessionário no lugar do cedente. O § 1º dispõe que a cessão do seguro não ocorrerá sem anuência prévia da seguradora quando o cessionário exercer atividade capaz de aumentar de forma relevante o risco ou não preencher os requisitos exigidos pela técnica de seguro, hipóteses em que o contrato será resolvido com a devolução proporcional do prêmio, ressalvado, na mesma proporção, o direito da seguradora às despesas incorridas. O § 2º dispõe que, caso a cessão implique alteração da taxa de prêmio, será feito o ajuste e creditada a diferença à parte favorecida. O § 3º dispõe que as bonificações, as taxações especiais e outras vantagens personalíssimas do cedente não se comunicam com o novo titular do interesse.'),
(109,'Comunicação da cessão do seguro à seguradora','A cessão do seguro correspondente deixará de ser eficaz se não for comunicada à seguradora nos 30 (trinta) dias posteriores à transferência do interesse garantido. O § 1º dispõe que a seguradora poderá, no prazo de 15 (quinze) dias, contado da comunicação, resolver o contrato. O § 2º dispõe que a recusa deverá ser notificada ao cedente e ao cessionário e produzirá efeitos após 15 (quinze) dias contados do recebimento da notificação. O § 3º dispõe que, se a seguradora resolver o contrato nos termos do § 1º, o segurado fará jus à devolução proporcional do prêmio, ressalvado, na mesma proporção, o direito da seguradora às despesas incorridas.'),
(110,'Cessão do seguro nos seguros obrigatórios','Nos seguros obrigatórios, a transferência do interesse garantido implica a cessão do seguro correspondente, independentemente da comunicação à seguradora.'),
(111,'Cessão do direito à indenização','A cessão do direito à indenização somente deverá ser comunicada para evitar que a seguradora efetue pagamento válido ao credor putativo.'),
(112,'Capital segurado nos seguros de vida e integridade física','Nos seguros sobre a vida e a integridade física, o capital segurado é livremente estipulado pelo proponente, que pode contratar mais de um seguro sobre o mesmo interesse, com a mesma ou com diversas seguradoras. O § 1º dispõe que o capital segurado, conforme convencionado, será pago sob a forma de renda ou de pagamento único. O § 2º dispõe que é lícita a estruturação de seguro sobre a vida e a integridade física com prêmio e capital variáveis.'),
(113,'Indicação do beneficiário','É livre a indicação do beneficiário nos seguros sobre a vida e a integridade física.'),
(114,'Substituição do beneficiário','Salvo renúncia do segurado, é lícita a substituição do beneficiário do seguro sobre a vida e a integridade física por ato entre vivos ou por declaração de última vontade. O parágrafo único dispõe que a seguradora não cientificada da substituição será exonerada pagando ao antigo beneficiário.'),
(115,'Falta de indicação de beneficiário e ordem de pagamento','Na falta de indicação do beneficiário ou se não prevalecer a indicação feita, o capital segurado será pago ou, se for o caso, será devolvida a reserva matemática por metade ao cônjuge, se houver, e o restante aos demais herdeiros do segurado. O § 1º dispõe que se considera ineficaz a indicação quando o beneficiário falecer antes da ocorrência do sinistro ou se ocorrer comoriência. O § 2º dispõe que, se o segurado for separado, ainda que de fato, caberá ao companheiro a metade que caberia ao cônjuge. O § 3º dispõe que, se não houver beneficiários indicados ou legais, o valor será pago àqueles que provarem que a morte do segurado os privou de meios de subsistência. O § 4º dispõe que, se a seguradora, ciente do sinistro, não identificar beneficiário ou dependente do segurado para subsistência no prazo prescricional da respectiva pretensão, o capital segurado será tido por abandonado, nos termos do inciso III do caput do art. 1.275 da Lei n. 10.406, de 10 de janeiro de 2002 (Código Civil), e será aportado no Fundo Nacional para Calamidades Públicas, Proteção e Defesa Civil (Funcap). O § 5º dispõe que não prevalecerá a indicação de beneficiário nas hipóteses de revogação da doação, observados os arts. 555, 556 e 557 da Lei n. 10.406, de 2002 (Código Civil).'),
(116,'Capital segurado por morte e herança','O capital segurado devido em razão de morte não é considerado herança para nenhum efeito. O parágrafo único dispõe que, para os fins do artigo, equipara-se ao seguro de vida a garantia de risco de morte do participante nos planos de previdência complementar.'),
(117,'Nulidade de renúncia ou redução do crédito ao capital segurado','É nulo, no seguro sobre a vida e a integridade física próprias, qualquer negócio jurídico que direta ou indiretamente implique renúncia ou redução do crédito ao capital segurado ou à reserva matemática, ressalvadas as atribuições feitas em favor do segurado ou dos beneficiários a título de empréstimo técnico ou resgate.'),
(118,'Prazo de carência nos seguros de vida e invalidez por doença','Nos seguros sobre a vida própria para o caso de morte e sobre a integridade física própria para o caso de invalidez por doença, é lícito estipular-se prazo de carência, durante o qual a seguradora não responde pela ocorrência do sinistro. O § 1º dispõe que o prazo de carência não pode ser convencionado quando se tratar de renovação ou de substituição de contrato existente, ainda que seja outra a seguradora. O § 2º dispõe que o prazo de carência não pode ser pactuado de forma a tornar inócua a garantia e em nenhum caso pode exceder a metade da vigência do contrato. O § 3º dispõe que, ocorrendo o sinistro no prazo de carência, legal ou contratual, a seguradora é obrigada a entregar ao segurado ou ao beneficiário o valor do prêmio pago, ou a reserva matemática, se houver. O § 4º dispõe que, convencionada a carência, a seguradora não poderá negar o pagamento do capital sob a alegação de preexistência de estado patológico.'),
(119,'Exclusão de estados patológicos preexistentes','É lícito, nos seguros sobre a vida e a integridade física, excluir da garantia os sinistros cuja causa exclusiva ou principal corresponda a estados patológicos preexistentes ao início da relação contratual. O parágrafo único dispõe que a exclusão somente poderá ser alegada quando não convencionado prazo de carência e desde que o segurado, questionado claramente, omita voluntariamente a informação da preexistência.'),
(120,'Suicídio e prazo de carência','O beneficiário não terá direito ao recebimento do capital segurado quando o suicídio voluntário do segurado ocorrer antes de completados 2 (dois) anos de vigência do seguro de vida. O § 1º dispõe que, quando o segurado aumentar o capital, o beneficiário não terá direito à quantia acrescida se ocorrer o suicídio no prazo do caput. O § 2º veda a fixação de novo prazo de carência, nas hipóteses de renovação e de substituição do contrato, ainda que seja outra a seguradora. O § 3º dispõe que o suicídio em razão de grave ameaça ou de legítima defesa de terceiro não está compreendido no prazo de carência. O § 4º dispõe que é nula a cláusula de exclusão de cobertura de suicídio de qualquer espécie. O § 5º dispõe que, ocorrendo o suicídio no prazo de carência, é assegurado o direito à devolução do montante da reserva matemática formada.')
) as v(n,c,a)
where l.codigo='lei15040' and l.numero=v.n and l.paragrafo is null and l.inciso is null and l.vigente;
